    std::vector<std::uint8_t> island_plunder_menus_source()
    {
        std::vector<std::uint8_t> bytes;
        bytes.reserve(island_plunder_menus_source_hex.size() / 2);
        const auto digit = [](char c) -> std::uint8_t
        {
            if (c >= '0' && c <= '9') return std::uint8_t(c - '0');
            if (c >= 'a' && c <= 'f') return std::uint8_t(c - 'a' + 10);
            throw std::runtime_error("invalid Source menus fixture");
        };
        for (std::size_t i = 0; i < island_plunder_menus_source_hex.size(); i += 2)
            bytes.push_back(std::uint8_t(16 * digit(island_plunder_menus_source_hex[i]) + digit(island_plunder_menus_source_hex[i+1])));
        return bytes;
    }

    void island_plunder_menus_translation_checks()
    {
        namespace abi = gsc::island_plunder_menus_native_abi;
        const auto source = island_plunder_menus_source();
        Check(source.size() == abi::source_length && abi::fingerprint(source) == abi::source_fingerprint,
            "Source164 menus script fingerprint changed");
        const auto reject = [](std::string_view name, std::vector<std::uint8_t> code)
        {
            const auto original = code;
            Check(!abi::translate_private_compiler_copy(name, code) && code == original,
                "Plunder menus ABI accepted or modified unverified input");
        };
        reject("scripts/mp/menus.gsc", source);
        reject("1827", source);
        reject(abi::source_module, {});
        auto short_code = source; short_code.pop_back(); reject(abi::source_module, short_code);
        auto long_code = source; long_code.push_back(0); reject(abi::source_module, long_code);
        for (auto pos : {std::size_t(0),source.size()-1,std::size_t(833),std::size_t(834),std::size_t(835),std::size_t(836),
                std::size_t(8090),std::size_t(8091),std::size_t(8092),std::size_t(8093)})
        {
            auto changed = source; changed[pos] ^= 1; reject(abi::source_module, changed);
        }
        auto patched = source;
        Check(abi::translate_private_compiler_copy(abi::source_module, patched),
            "Plunder menus ABI rejected exact installed Source164 bytes");
        Check(abi::fingerprint(patched) == abi::replay_fingerprint && patched[834] == 0xC2 && patched[8091] == 0xC2,
            "Plunder menus native test-client IDs are incorrect");
        for(std::size_t i = 0; i < patched.size(); ++i)
            Check(patched[i] == source[i] || i == 834 || i == 8091,
                "Plunder menus ABI changed unrelated script code");
        reject(abi::source_module, patched);
        auto tampered = source;
        Check(!abi::translate_exact_profile(abi::source_module, tampered, abi::source_fingerprint,
            abi::replay_fingerprint ^ 1) && tampered == source,
            "Plunder menus ABI failed to roll back on unexpected translated hash");
    }
